import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> [side, price, qty_remaining, seq]
    seq_counter = 0

    def add_resting(id_, side, price, qty, seq):
        book[id_] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            id_ = o[1]
            entry = book.get(id_)
            if entry is not None and entry[2] > 0:
                entry[2] = 0
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'market':
            _, id_, side, qty = o
            price = None
        else:
            # limit or ioc
            _, id_, side, price, qty = o

        remaining = qty

        if side == 'buy':
            heap = sell_heap
            def price_ok(p, price=price):
                return (price is None) or (p <= price)
        else:
            heap = buy_heap
            def price_ok(p, price=price):
                return (price is None) or (p >= price)

        while remaining > 0 and heap:
            top = heap[0]
            if side == 'buy':
                p, s, oid = top
            else:
                neg_p, s, oid = top
                p = -neg_p

            entry = book.get(oid)
            if entry is None or entry[2] <= 0:
                heapq.heappop(heap)
                continue

            if not price_ok(p):
                break

            trade_qty = min(remaining, entry[2])

            if side == 'buy':
                trades.append([id_, oid, p, trade_qty])
            else:
                trades.append([oid, id_, p, trade_qty])

            remaining -= trade_qty
            entry[2] -= trade_qty

            if entry[2] == 0:
                heapq.heappop(heap)

        if typ == 'limit' and remaining > 0:
            add_resting(id_, side, price, remaining, seq)
        # ioc and market discard remainder; limit fully filled needs no resting entry
        # but we still want to record fully-filled limit orders in book as inactive (qty 0)
        if typ == 'limit' and id_ not in book:
            book[id_] = [side, price, remaining, seq]

    return trades

